for (const s of ['body','ul.navbar-nav','header.py-5','body > div.py-5','.lead','.navbar-brand','a.nav-link:not(.active)']){
const r=await p.$eval(s,e=>{const c=getComputedStyle(e);const o={};for(const k of ['fontFamily','fontSize','fontWeight','letterSpacing','wordSpacing','color','backgroundImage','backgroundSize','backgroundPosition','backgroundRepeat','backgroundAttachment','opacity','filter','mixBlendMode','fontStretch','fontKerning','fontVariationSettings','textRendering','paddingTop','marginBottom','display','gap','width'])o[k]=c[k];return o});
console.log(s,JSON.stringify(r));}
await b.close()})()
